import { I, dish } from "./catalog-kit.ts";
import type { Recipe } from "./types";

function x(
  id: string,
  name: string,
  cuisine: string,
  tags: string[],
  protein: Recipe["protein"],
  plate: Recipe["plate"],
  minutes: number,
  description: string,
  ingredients: Recipe["ingredients"],
  steps: string[],
  aliases: string[] = [],
  nutrition?: Recipe["nutrition"],
): Recipe {
  return dish({
    id,
    name,
    cuisine,
    description,
    minutes,
    protein,
    plate,
    tags: Array.from(new Set(tags)),
    aliases,
    ingredients,
    steps,
    nutrition,
  });
}

